defined('ABSPATH') || exit;
function prime_response_text(){return 'We aim to reply within 2 hours during the day, and always within 24 hours.';}
function prime_estimate_link($service='',$args=[]){return add_query_arg(array_merge($service?['prime_service'=>$service]:[],$args),prime_page_link('prices')).'#estimate';}
function prime_launch_list($items){$html='';foreach($items as $item)$html.=prime_b('list-item','<li>'.esc_html($item).'</li>');return prime_b('list','<ul class="wp-block-list">'.$html.'</ul>');}
function prime_launch_cards($cards,$class=''){return prime_cols(array_map(function($card){return prime_g(prime_h($card[0],3).prime_p($card[1]).($card[2]??''),'pp-card');},$cards),$class);}
function prime_launch_cta($heading,$service='',$copy=''){return prime_section(prime_g(prime_cols([prime_h($heading).prime_p($copy?:prime_response_text()),prime_buttons('Get my estimate',prime_estimate_link($service)).prime_buttons('WhatsApp us','https://wa.me/61491245156',true).prime_buttons('Call us','tel:+61491245156',true)]),'pp-cta'));}
function prime_launch_checklist($rooms,$excluded){$panels='';foreach($rooms as $room=>$copy)$panels.=prime_b('details','<details class="wp-block-details"><summary>'.esc_html($room).'</summary>'.prime_p($copy).'</details>');return prime_section(prime_h("What's included").prime_cols([prime_g($panels,'pp-card pp-room-list'),prime_g(prime_h("What's not included",3).prime_launch_list($excluded),'pp-soft-card')],'pp-two-thirds'));}
function prime_launch_reviews($title){return prime_sc('[prime_reviews heading="'.esc_attr($title).'"]');}
